    if b["terminal_result"] not in RES: errs.append(f"{i} res")
    if b["terminal_error"] not in ERR: errs.append(f"{i} err")
    # error consistency
    if b["terminal_result"] in ("winner","ace","unreturnable") and b["terminal_error"]!="none":
